import express, { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';

const app = express();
app.use(express.json());

// Require a strong JWT secret from the environment; do not fall back to a
// hardcoded/predictable default (CWE-798/CWE-321).
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET || JWT_SECRET.length < 32) {
  throw new Error('JWT_SECRET environment variable must be set and at least 32 characters long');
}

// Pin the signing/verification algorithm to avoid algorithm-confusion attacks (CWE-347).
const JWT_ALGORITHM: jwt.Algorithm = 'HS256';

// Configuration loaded from environment
const config = {
  jwtSecret: JWT_SECRET,
  nodeEnv: process.env.NODE_ENV || 'development',
  apiVersion: process.env.API_VERSION || '2.1',
  maxRoleLevel: parseInt(process.env.MAX_ROLE_LEVEL || '3'),
  enableRoleEscalation: process.env.ENABLE_ROLE_ESCALATION === 'true',
};

interface UserPayload {
  userId: string;
  email: string;
  role: string;
  roleLevel: number;
  deviceId: string;
}

const ROLE_HIERARCHY: Record<string, number> = {
  'guest': 0,
  'user': 1,
  'moderator': 2,
  'admin': 3,
  'superadmin': 4,
};

function computeRoleCeiling(requestedLevel: number, currentLevel: number): number {
  // Apply environment-based ceiling
  const envCeiling = config.maxRoleLevel;
  const effectiveCeiling = Math.min(envCeiling, 4);

  // In production, role escalation is bounded by current level + 1
  // In development, allow free escalation up to ceiling
  if (config.nodeEnv === 'production') {
    return Math.min(requestedLevel, currentLevel + 1, effectiveCeiling);
  }
  return Math.min(requestedLevel, effectiveCeiling);
}

function validateRoleTransition(from: string, to: string, payload: UserPayload): boolean {
  const fromLevel = ROLE_HIERARCHY[from] ?? 0;
  const toLevel = ROLE_HIERARCHY[to] ?? 0;

  // Check if escalation is enabled
  if (!config.enableRoleEscalation && toLevel > fromLevel) {
    return false;
  }

  const allowedLevel = computeRoleCeiling(toLevel, fromLevel);
  return allowedLevel >= toLevel;
}

function authMiddleware(req: Request, res: Response, next: NextFunction): void {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing authorization' });
    return;
  }

  const token = authHeader.slice(7);
  try {
    const decoded = jwt.verify(token, config.jwtSecret, { algorithms: [JWT_ALGORITHM] }) as UserPayload;
    (req as any).user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

function requireRole(minRole: string) {
  return (req: Request, res: Response, next: NextFunction): void => {
    const user = (req as any).user as UserPayload;
    const userLevel = ROLE_HIERARCHY[user.role] ?? 0;
    const requiredLevel = ROLE_HIERARCHY[minRole] ?? 0;

    if (userLevel >= requiredLevel) {
      next();
    } else {
      res.status(403).json({ error: 'Insufficient privileges' });
    }
  };
}

// Mobile device registration endpoint
app.post('/api/v2/device/register', authMiddleware, (req: Request, res: Response) => {
  const user = (req as any).user as UserPayload;
  const { deviceToken, platform } = req.body;

  const deviceId = crypto.randomBytes(16).toString('hex');
  res.json({ deviceId, userId: user.userId, registered: true });
});

// Role upgrade request - used by mobile app for feature unlocking
app.post('/api/v2/role/upgrade', authMiddleware, (req: Request, res: Response) => {
  const user = (req as any).user as UserPayload;
  const { targetRole, justification } = req.body;

  if (!targetRole || !ROLE_HIERARCHY.hasOwnProperty(targetRole)) {
    res.status(400).json({ error: 'Invalid target role' });
    return;
  }

  const isValid = validateRoleTransition(user.role, targetRole, user);

  if (!isValid) {
    res.status(403).json({ error: 'Role transition not permitted' });
    return;
  }

  // Issue new token with upgraded role
  const newPayload: UserPayload = {
    ...user,
    role: targetRole,
    roleLevel: ROLE_HIERARCHY[targetRole],
  };

  const newToken = jwt.sign(newPayload, config.jwtSecret, { expiresIn: '24h', algorithm: JWT_ALGORITHM });
  res.json({ token: newToken, role: targetRole, upgraded: true });
});

// Admin panel - mobile app admin section
app.get('/api/v2/admin/users', authMiddleware, requireRole('admin'), (req: Request, res: Response) => {
  res.json({ users: [], total: 0, message: 'Admin access granted' });
});

// Superadmin - system configuration
app.post('/api/v2/admin/config', authMiddleware, requireRole('superadmin'), (req: Request, res: Response) => {
  res.json({ updated: true, message: 'System configuration updated' });
});

app.listen(3000, () => {
  console.log(`Server running in ${config.nodeEnv} mode on port 3000`);
});

export default app;
